/**
 * Operational intelligence — deterministic rules over the shared simulation state.
 *
 * Produces the insights, recommendations and "next actions" shown in the Command Center,
 * the equipment inspector and the copilot. Every statement is computed from the same
 * metrics the dashboards show and carries its evidence; nothing is generated by an LLM.
 */
import { EQUIPMENT_BY_ID } from '../data/equipment';
import { BUFFERS, DEFECTS, LINE, M2_PER_TILE, OPS_BY_ID, REASON_BY_CODE, STAGES, STAGE_BY_ID, TARGET } from '../model/plant';
import type { DefectCategory, StageId } from '../model/types';
import { batchAt, type SimState } from '../sim/engine';
import { CONSUMER_BY_ID, DEFAULT_TARIFFS, type Tariffs } from '../sim/energy';
import { HEALTH_ASSETS, assess, formatH, type HealthAssessment } from '../sim/health';
import {
  bottleneck,
  defectShift,
  downtimePareto,
  energyIn,
  eventDuration,
  fleetMetrics,
  kilnIdleBurn,
  lineMetrics,
  qualityIn,
  resolvePeriod,
  type Period,
} from '../sim/metrics';
import { formatClock, formatDuration } from '../sim/time';

export type InsightSeverity = 'critical' | 'serious' | 'warning' | 'info' | 'positive';
export type InsightKind = 'target' | 'stoppage' | 'bottleneck' | 'buffer' | 'quality' | 'health' | 'energy' | 'logistics' | 'shift';

export type InsightLink =
  | { kind: 'equipment'; id: string; label: string }
  | { kind: 'vehicle'; id: string; label: string }
  | { kind: 'workspace'; id: 'production' | 'quality' | 'health' | 'energy' | 'fleet' | 'command' | 'scenarios'; label: string };

export type Insight = {
  id: string;
  kind: InsightKind;
  severity: InsightSeverity;
  title: string;
  /** One-sentence explanation. */
  summary: string;
  /** Facts the insight is based on (traceable to metrics). */
  evidence: string[];
  /** Quantified effect, if any. */
  impact?: string;
  recommendation?: string;
  equipmentId?: string;
  links: InsightLink[];
  /** Ordering weight (higher first). */
  weight: number;
};

const RANK: Record<InsightSeverity, number> = { critical: 500, serious: 400, warning: 300, info: 100, positive: 50 };
const m2 = (tiles: number) => Math.round(tiles * M2_PER_TILE).toLocaleString('en-GB');
const pct = (f: number, d = 1) => `${(f * 100).toFixed(d)} %`;
const name = (id: string) => EQUIPMENT_BY_ID[id]?.name ?? id;

/** First response for each downtime reason (illustrative standard work). */
export const REASON_ACTIONS: Record<string, string> = {
  MECH_HYD: 'Dispatch maintenance to check hydraulic pressure, pump and valves; confirm accumulator pre-charge before restart.',
  MECH_DIE: 'Change the damaged punch/die set from the tool store; inspect the last pressed tiles for cracks.',
  MECH_ROLLER: 'Clear the roller jam, remove broken tiles from the channel and check roller alignment before restart.',
  MECH_BELT: 'Re-track the belt and check the tensioner; look for spillage that caused the drift.',
  MECH_BEARING: 'Isolate and inspect the bearing; replace from stores and verify lubrication before restart.',
  MECH_CARTON: 'Clear the carton jam, check blank quality and glue temperature.',
  MECH_GRIPPER: 'Inspect gripper vacuum cups and air supply; recalibrate the pick position.',
  MECH_NOZZLE: 'Swap to the standby atomiser and inspect the wheel/nozzles for wear.',
  ELEC_DRIVE: 'Read the drive fault code, reset and check motor insulation; call electrical maintenance if it recurs.',
  ELEC_SENSOR: 'Clean or replace the faulty sensor and verify the signal before restart.',
  ELEC_BURNER: 'Check flame detection and gas train; restart the burner sequence under supervision.',
  ELEC_PRINTHEAD: 'Run a printhead purge and nozzle check; replace the head if missing nozzles persist.',
  ELEC_ROBOT: 'Read the robot controller alarm, run diagnostics and re-home the robot.',
  PROC_MOISTURE: 'Adjust spray-dryer inlet temperature and slip feed to bring powder moisture back into spec.',
  PROC_DENSITY: 'Correct slip density (water / deflocculant dosing) before resuming milling.',
  PROC_VISCOSITY: 'Correct glaze viscosity and density; flush the bell before restart.',
  PROC_INK: 'Restore ink supply (tank level, filters, degassing) and run a test print.',
  PROC_TEMP: 'Check burner settings and thermocouples against the firing curve.',
  CHG_PRODUCT: 'Follow the changeover checklist; verify first-off tiles before releasing the line.',
  SCN_STOP: 'Dispatch maintenance to diagnose the stoppage; prepare the line to restart in sequence.',
};

/** Process conditions to investigate per defect category. */
export const DEFECT_ACTIONS: Record<DefectCategory, string> = {
  crack: 'Check press specific pressure and powder moisture/granulometry; inspect the die and green-tile handling.',
  chip: 'Inspect roller alignment and transfer points after the kiln; check for tile collisions at the sorter.',
  surface: 'Check glaze filtration and booth cleanliness; look for dust contamination before glazing.',
  glaze: 'Check glaze density, viscosity and bell flow rate; verify tile temperature at glazing.',
  shade: 'Recalibrate the inkjet colour profile and check kiln firing-zone temperatures for drift.',
  planarity: 'Review the kiln firing and cooling curves (top/bottom temperature balance).',
  dimension: 'Check press die wear and powder fill; verify kiln shrinkage against the firing curve.',
};

// ── Rules ─────────────────────────────────────────────────────────────────────

function targetRule(s: SimState, p: Period): Insight[] {
  const lm = lineMetrics(s, p);
  if (lm.attainment == null || lm.target < 1) return [];
  const gap = lm.target - lm.output;
  const pareto = downtimePareto(s, p).slice(0, 3);
  const bn = bottleneck(s);
  if (lm.attainment >= 0.98) {
    return [
      {
        id: 'target-ok',
        kind: 'target',
        severity: 'positive',
        title: `Output on target · ${pct(lm.attainment, 0)}`,
        summary: `${m2(lm.output)} m² first-quality output against a ${m2(lm.target)} m² target for ${p.label.toLowerCase()}.`,
        evidence: [`Line OEE ${lm.oee.oee.status === 'ok' ? pct(lm.oee.oee.value!) : '—'} (target ${pct(TARGET.oeeTarget, 0)}).`],
        links: [{ kind: 'workspace', id: 'production', label: 'Production & OEE' }],
        weight: RANK.positive,
      },
    ];
  }
  const ev = [
    `Output ${m2(lm.output)} m² vs target ${m2(lm.target)} m² (${pct(lm.attainment, 0)}).`,
    `Line OEE ${lm.oee.oee.status === 'ok' ? pct(lm.oee.oee.value!) : '—'}: availability ${lm.oee.availability.status === 'ok' ? pct(lm.oee.availability.value!) : '—'}, performance ${lm.oee.performance.status === 'ok' ? pct(lm.oee.performance.value!) : '—'}, quality ${lm.oee.quality.status === 'ok' ? pct(lm.oee.quality.value!) : '—'}.`,
  ];
  if (pareto.length) ev.push(`Largest unplanned losses: ${pareto.map((r) => `${r.label} ${Math.round(r.minutes)} min`).join(', ')}.`);
  ev.push(`Current constraint: ${bn.current.name} (active ${pct(bn.current.activeShare, 0)} of the last 2 h).`);
  return [
    {
      id: 'target-gap',
      kind: 'target',
      severity: lm.attainment < 0.9 ? 'serious' : 'warning',
      title: `Behind target by ${m2(gap)} m²`,
      summary: `${p.label} output is ${pct(lm.attainment, 0)} of target; the gap is driven by ${pareto[0] ? `${pareto[0].label.toLowerCase()} and ` : ''}time lost at the ${bn.current.name.toLowerCase()} stage.`,
      evidence: ev,
      impact: `${m2(gap)} m² behind plan`,
      recommendation: `Protect the constraint (${bn.current.name}): keep its input buffer full and prioritise its repairs; then address ${pareto[0]?.label.toLowerCase() ?? 'the top downtime reason'}.`,
      links: [{ kind: 'workspace', id: 'production', label: 'Production & OEE' }],
      weight: RANK[lm.attainment < 0.9 ? 'serious' : 'warning'] + gap / 50,
    },
  ];
}

function stoppageRule(s: SimState): Insight[] {
  const now = s.minute;
  return s.downtime
    .filter((d) => d.end == null && !REASON_BY_CODE[d.reasonCode].planned && d.category !== 'Starved' && d.category !== 'Blocked')
    .map((d) => {
      const stage = OPS_BY_ID[d.equipmentId].stage!;
      const isConstraint = stage === LINE.designConstraint || bottleneck(s).current.stage === stage;
      const minutes = eventDuration(d, now);
      const sev = isConstraint || d.equipmentId === 'H-KILN' ? 'critical' : 'serious';
      const outBuf = STAGES[STAGES.findIndex((x) => x.id === stage) + 1]?.inputBuffer;
      const buf = outBuf ? BUFFERS.find((b) => b.id === outBuf) : null;
      const downstream = buf ? s.buffers[buf.id] : 0;
      const downstreamRate = STAGES.find((x) => x.inputBuffer === outBuf)?.machines.reduce((a, id) => a + (OPS_BY_ID[id].idealRatePerHour ?? 0), 0) ?? 0;
      const cover = buf && downstreamRate ? (downstream / downstreamRate) * 60 : null;
      return {
        id: `stop-${d.id}`,
        kind: 'stoppage' as const,
        severity: sev as InsightSeverity,
        title: `${d.equipmentId} stopped · ${REASON_BY_CODE[d.reasonCode].label}`,
        summary: `${name(d.equipmentId)} has been down for ${formatDuration(minutes)} (since ${formatClock(d.start)})${d.source === 'scenario' ? ' — scenario input' : ''}.`,
        evidence: [
          `Lost output so far ≈ ${m2(d.lostTiles)} m² at ideal rate.`,
          d.constraintImpactMin > 0 ? `The line constraint has been held up for ${Math.round(d.constraintImpactMin)} min while it is down.` : 'The line constraint has not been held up yet.',
          ...(cover != null && buf ? [`Downstream buffer (${buf.name}) covers ≈ ${Math.round(cover)} min of downstream demand.`] : []),
        ],
        impact: `${m2(d.lostTiles)} m² lost so far`,
        recommendation: REASON_ACTIONS[d.reasonCode] ?? 'Dispatch maintenance to diagnose the stoppage.',
        equipmentId: d.equipmentId,
        links: [
          { kind: 'equipment' as const, id: d.equipmentId, label: `Locate ${d.equipmentId}` },
          { kind: 'workspace' as const, id: 'production' as const, label: 'Downtime events' },
        ],
        weight: RANK[sev] + minutes,
      };
    });
}

function bottleneckRule(s: SimState): Insight[] {
  const bn = bottleneck(s);
  const cur = bn.current;
  const machines = STAGE_BY_ID[cur.stage].machines;
  const up = bn.ranked.filter((r) => r.blockedShare > 0.05).map((r) => r.name);
  const down = bn.ranked.filter((r) => r.starvedShare > 0.05).map((r) => r.name);
  const ev = [
    `${cur.name} was active ${pct(cur.activeShare, 0)} of the last 2 h (starved ${pct(cur.starvedShare, 0)}, blocked ${pct(cur.blockedShare, 0)}).`,
  ];
  if (up.length) ev.push(`Blocked upstream: ${up.join(', ')}.`);
  if (down.length) ev.push(`Starved downstream: ${down.join(', ')}.`);
  if (cur.inputBufferLevel != null) ev.push(`Its input buffer is at ${pct(cur.inputBufferLevel, 0)}.`);
  return [
    {
      id: 'bottleneck',
      kind: 'bottleneck',
      severity: bn.shifted ? 'warning' : 'info',
      title: bn.shifted ? `Bottleneck shifted to ${cur.name}` : `Constraint: ${cur.name}`,
      summary: bn.shifted
        ? `The line is limited by ${cur.name.toLowerCase()} rather than the designed constraint (${STAGE_BY_ID[LINE.designConstraint].name.toLowerCase()}); every minute lost there is lost for the whole line.`
        : `${cur.name} is the line constraint, as designed.`,
      evidence: ev,
      recommendation: bn.shifted
        ? `Restore ${cur.name.toLowerCase()} capacity (${machines.join(', ')}): check rate settings and recent stops; until then reduce upstream overproduction.`
        : `Keep ${cur.name.toLowerCase()} fed: avoid starving it from upstream and schedule its maintenance in planned windows.`,
      equipmentId: machines[0],
      links: machines.map((id) => ({ kind: 'equipment' as const, id, label: `Locate ${id}` })),
      weight: RANK[bn.shifted ? 'warning' : 'info'] + cur.activeShare * 10,
    },
  ];
}

function bufferRule(s: SimState): Insight[] {
  const out: Insight[] = [];
  STAGES.forEach((st, i) => {
    if (!st.inputBuffer || i === 0) return;
    const buf = BUFFERS.find((b) => b.id === st.inputBuffer)!;
    if (buf.capacity < 500) return; // conveyor accumulations change too fast to be useful
    const inflow = STAGES[i - 1].machines.reduce((a, id) => a + s.machines[id].ratePerHour, 0);
    const outflow = st.machines.reduce((a, id) => a + s.machines[id].ratePerHour, 0);
    const level = s.buffers[buf.id];
    const net = inflow - outflow;
    if (net >= -50 || level <= 0) return;
    const minutesToEmpty = (level / -net) * 60;
    if (minutesToEmpty > 90) return;
    out.push({
      id: `buffer-${buf.id}`,
      kind: 'buffer',
      severity: minutesToEmpty < 30 ? 'serious' : 'warning',
      title: `${buf.name} empties in ≈ ${Math.round(minutesToEmpty)} min`,
      summary: `${STAGES[i - 1].name} is supplying ${Math.round(inflow)} tiles/h while ${st.name.toLowerCase()} draws ${Math.round(outflow)} tiles/h; ${st.name.toLowerCase()} will be starved when the buffer runs out.`,
      evidence: [`Buffer level ${pct(level / buf.capacity, 0)} of ${buf.capacity.toLocaleString('en-GB')} tiles.`],
      recommendation: `Restore ${STAGES[i - 1].name.toLowerCase()} output before the buffer empties, or plan a controlled slow-down of ${st.name.toLowerCase()}.`,
      equipmentId: buf.equipmentId ?? st.machines[0],
      links: [{ kind: 'equipment', id: buf.equipmentId ?? st.machines[0], label: `Locate ${buf.name}` }],
      weight: RANK[minutesToEmpty < 30 ? 'serious' : 'warning'] + (90 - minutesToEmpty),
    });
  });
  return out;
}

function qualityRule(s: SimState): Insight[] {
  const now = s.minute;
  const recent = qualityIn(s, { from: Math.floor((now - 60) / 60) * 60, to: now, label: '' });
  const ref = qualityIn(s, { from: Math.floor((now - 60 - 1440) / 60) * 60, to: Math.floor((now - 60) / 60) * 60, label: '' });
  if (recent.inspected < 300 || ref.inspected < 1000) return [];
  const rr = recent.rejected / recent.inspected;
  const rref = ref.rejected / ref.inspected;
  const shift = defectShift(s, 120, 1440)[0];
  const rising = shift && shift.ratio != null && shift.ratio > 1.6 && (shift.rateRecent ?? 0) > 0.004;
  if (rr < rref * 1.35 && !rising) return [];
  const d = shift.defect;
  const origin = DEFECTS[d].origin as StageId;
  const batch = batchAt(s, now - 180);
  const scenario = s.scenarios.some((sc) => sc.kind === 'quality-deterioration' && sc.start <= now && (sc.end == null || sc.end > now));
  return [
    {
      id: 'quality',
      kind: 'quality',
      severity: rr > 0.05 ? 'serious' : 'warning',
      title: `Reject rate ${pct(rr)} · ${shift.label.toLowerCase()} rising`,
      summary: `Rejects at sorting are ${(rr / rref).toFixed(1)}× the 24-hour reference (${pct(rref)}); ${shift.label.toLowerCase()} is up ${shift.ratio!.toFixed(1)}× and originates at ${STAGE_BY_ID[origin].name.toLowerCase()}.${scenario ? ' (Scenario input active.)' : ''}`,
      evidence: [
        `Last hour: ${Math.round(recent.rejected)} of ${Math.round(recent.inspected)} inspected tiles rejected.`,
        `${shift.label}: ${pct(shift.rateRecent ?? 0, 2)} of tiles in the last 2 h vs ${pct(shift.rateRef ?? 0, 2)} before.`,
        `Affected batch: ${batch.id} (tiles fired ≈ 3 h after pressing).`,
      ],
      impact: `≈ ${m2(recent.rejected - recent.inspected * rref)} m²/h of extra rejects`,
      recommendation: DEFECT_ACTIONS[d],
      equipmentId: STAGE_BY_ID[origin].machines[0],
      links: [
        { kind: 'equipment', id: 'I-VIS', label: 'Locate inspection tunnel' },
        { kind: 'equipment', id: STAGE_BY_ID[origin].machines[0], label: `Origin: ${STAGE_BY_ID[origin].name}` },
        { kind: 'workspace', id: 'quality', label: 'Quality Intelligence' },
      ],
      weight: RANK[rr > 0.05 ? 'serious' : 'warning'] + rr * 1000,
    },
  ];
}

export function healthAssessments(s: SimState): HealthAssessment[] {
  return HEALTH_ASSETS.map((a) => assess(s, a.id));
}

function healthRule(s: SimState): Insight[] {
  return healthAssessments(s)
    .filter((h) => h.level === 'watch' || h.level === 'warning' || h.level === 'alarm')
    .map((h) => {
      const sev: InsightSeverity = h.level === 'alarm' ? 'critical' : h.level === 'warning' ? 'serious' : 'warning';
      const comp = HEALTH_ASSETS.find((a) => a.id === h.id)!.component;
      return {
        id: `health-${h.id}`,
        kind: 'health' as const,
        severity: sev,
        title: `${h.id} ${h.level === 'watch' ? 'health watch' : h.level === 'warning' ? 'abnormal trend' : 'alarm limit reached'} · ${comp.split(' · ')[1] ?? comp}`,
        summary: `${name(h.id)}: health score ${h.score}/100${h.etaTripH != null ? `; trip limit in ≈ ${formatH(h.etaTripH)} if the trend continues` : ''}.`,
        evidence: h.findings.length ? h.findings : ['Signals within limits but trending.'],
        impact: h.impact ?? undefined,
        recommendation: h.recommendation ?? undefined,
        equipmentId: h.id,
        links: [
          { kind: 'equipment' as const, id: h.id, label: `Locate ${h.id}` },
          { kind: 'workspace' as const, id: 'health' as const, label: 'Machine Health' },
        ],
        weight: RANK[sev] + (100 - h.score),
      };
    });
}

function energyRule(s: SimState, tariffs: Tariffs): Insight[] {
  const now = s.minute;
  const p: Period = { from: Math.floor((now - 120) / 60) * 60, to: now, label: 'Last 2 h' };
  const e = energyIn(s, p, tariffs);
  const out: Insight[] = [];
  for (const r of e.rows) {
    if (r.deviation == null || r.deviation < 0.08 || r.expected < 50) continue;
    const hours = (p.to - p.from) / 60;
    const excessPerH = (r.cost - r.expectedCost) / hours;
    out.push({
      id: `energy-${r.id}`,
      kind: 'energy',
      severity: r.deviation > 0.15 ? 'serious' : 'warning',
      title: `Energy anomaly · ${r.label} +${(r.deviation * 100).toFixed(0)} %`,
      summary: `${r.label} used ${Math.round(r.total).toLocaleString('en-GB')} kWh in the last 2 h against ${Math.round(r.expected).toLocaleString('en-GB')} kWh expected by the energy model for the same production.`,
      evidence: [`Excess ≈ ${Math.round(r.total - r.expected).toLocaleString('en-GB')} kWh (${tariffs.currency} ${(r.cost - r.expectedCost).toFixed(0)}).`],
      impact: `${tariffs.currency} ${excessPerH.toFixed(0)}/h · ≈ ${tariffs.currency} ${(excessPerH * 24 * 30).toLocaleString('en-GB', { maximumFractionDigits: 0 })}/month if sustained`,
      recommendation: CONSUMER_BY_ID[r.id]?.thermal
        ? 'Check combustion air/gas ratio, burner tuning and flue-gas O₂; inspect for air ingress and insulation damage.'
        : 'Check for compressed-air leaks, motor load and power factor; compare against the last service readings.',
      equipmentId: r.id,
      links: [
        { kind: 'equipment', id: r.id === 'A-SUB' ? 'A-SUB' : r.id, label: `Locate ${r.id}` },
        { kind: 'workspace', id: 'energy', label: 'Energy Intelligence' },
      ],
      weight: RANK[r.deviation > 0.15 ? 'serious' : 'warning'] + r.deviation * 100,
    });
  }
  const sh = resolvePeriod('shift', now);
  const idle = kilnIdleBurn(s, sh);
  if (idle > 1500)
    out.push({
      id: 'energy-kiln-idle',
      kind: 'energy',
      severity: 'info',
      title: `Kiln burnt ${Math.round(idle).toLocaleString('en-GB')} kWh while waiting for tiles`,
      summary: 'The kiln keeps firing when it is starved; every minute without input costs gas without output.',
      evidence: [`Starved/blocked kiln time this shift: ${Math.round(sumIdle(s, sh))} min.`],
      impact: `${tariffs.currency} ${(idle * tariffs.gas).toFixed(0)} of gas this shift`,
      recommendation: 'Reduce kiln starvation by protecting the glazing and decoration feed; use idle-mode firing setpoints for planned gaps.',
      equipmentId: 'H-KILN',
      links: [{ kind: 'equipment', id: 'H-KILN', label: 'Locate kiln' }],
      weight: RANK.info + idle / 500,
    });
  return out;
}
const sumIdle = (s: SimState, p: Period) => {
  let m = 0;
  for (let h = Math.floor(p.from / 60); h * 60 < p.to; h++) {
    const b = s.hours['H-KILN']?.get(h);
    if (b) m += b.starved + b.blocked;
  }
  return m;
};

function logisticsRule(s: SimState): Insight[] {
  const out: Insight[] = [];
  const fm = fleetMetrics(s, resolvePeriod('shift', s.minute));
  if (fm.waiting >= 3)
    out.push({
      id: 'yard',
      kind: 'logistics',
      severity: fm.waiting >= 5 ? 'serious' : 'warning',
      title: `${fm.waiting} trucks waiting for a dock`,
      summary: `All docks are occupied or reserved; ${fm.waiting} outbound trucks are queuing in the holding area.`,
      evidence: [`Dock utilisation this shift ${pct(fm.dockUtilisation, 0)}; average gate→dock ${fm.avgGateToDock != null ? `${Math.round(fm.avgGateToDock)} min` : '—'}.`],
      recommendation: 'Release docks faster (pre-stage pallets, add a loading forklift) or re-sequence arrivals with carriers.',
      links: [
        { kind: 'equipment', id: 'A-HOLD', label: 'Locate holding area' },
        { kind: 'workspace', id: 'fleet', label: 'Fleet & Logistics' },
      ],
      weight: RANK[fm.waiting >= 5 ? 'serious' : 'warning'] + fm.waiting,
    });
  for (const [dockId, d] of Object.entries(s.logistics.docks)) {
    if (!d.vehicleId || d.since == null || s.minute - d.since < 75) continue;
    const v = s.logistics.vehicles[d.vehicleId];
    out.push({
      id: `dock-${dockId}`,
      kind: 'logistics',
      severity: 'warning',
      title: `${v.label} at dock for ${formatDuration(s.minute - d.since)}`,
      summary: 'Prolonged dock stay blocks the dock for the next truck.',
      evidence: [`Docked since ${formatClock(d.since)}.`],
      recommendation: 'Check paperwork / loading status with the dock supervisor and release the dock.',
      links: [
        { kind: 'vehicle', id: v.id, label: `Follow ${v.label}` },
        { kind: 'workspace', id: 'fleet', label: 'Fleet & Logistics' },
      ],
      weight: RANK.warning + (s.minute - d.since) / 10,
    });
  }
  return out;
}

function shiftRule(s: SimState): Insight[] {
  const prev = lineMetrics(s, resolvePeriod('prev-shift', s.minute));
  const cur = lineMetrics(s, resolvePeriod('shift', s.minute));
  if (prev.oee.oee.status !== 'ok' || cur.oee.oee.status !== 'ok' || cur.period.to - cur.period.from < 60) return [];
  const d = (cur.oee.oee.value! - prev.oee.oee.value!) * 100;
  if (Math.abs(d) < 2) return [];
  return [
    {
      id: 'shift-compare',
      kind: 'shift',
      severity: d > 0 ? 'positive' : 'info',
      title: `OEE ${d > 0 ? 'up' : 'down'} ${Math.abs(d).toFixed(1)} pts vs previous shift`,
      summary: `Current shift ${pct(cur.oee.oee.value!)} vs ${pct(prev.oee.oee.value!)} in ${prev.period.label}.`,
      evidence: [`Previous shift output ${m2(prev.output)} m² (${prev.attainment != null ? pct(prev.attainment, 0) : '—'} of target).`],
      links: [{ kind: 'workspace', id: 'production', label: 'Shift performance' }],
      weight: RANK[d > 0 ? 'positive' : 'info'],
    },
  ];
}

/** All current insights, most important first. */
export function insights(s: SimState, opts: { period?: Period; tariffs?: Tariffs } = {}): Insight[] {
  const p = opts.period ?? resolvePeriod('shift', s.minute);
  const tariffs = opts.tariffs ?? DEFAULT_TARIFFS;
  return [
    ...stoppageRule(s),
    ...healthRule(s),
    ...qualityRule(s),
    ...energyRule(s, tariffs),
    ...bufferRule(s),
    ...bottleneckRule(s),
    ...targetRule(s, p),
    ...logisticsRule(s),
    ...shiftRule(s),
  ].sort((a, b) => b.weight - a.weight);
}

/** Recommendations relevant to one asset (inspector "AI recommendations"). */
export function recommendationsFor(s: SimState, equipmentId: string, opts: { tariffs?: Tariffs } = {}): Insight[] {
  const stage = OPS_BY_ID[equipmentId]?.stage;
  return insights(s, opts).filter(
    (i) =>
      i.equipmentId === equipmentId ||
      i.links.some((l) => l.kind === 'equipment' && l.id === equipmentId) ||
      (stage && i.kind === 'bottleneck' && STAGE_BY_ID[stage].machines.includes(i.equipmentId ?? '')),
  );
}

/** Prioritised next actions (insights that carry a recommendation). */
export function nextActions(s: SimState, opts: { tariffs?: Tariffs } = {}) {
  return insights(s, opts)
    .filter((i) => i.recommendation && i.severity !== 'positive')
    .slice(0, 6);
}
